import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import {} from '@/primitives';
import {} from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container
  const root = new Group();

  // Plane geometry (size based on typical card aspect)
  const geometry = new PlaneGeometry(7, 6);
  const material = new MeshBasicNodeMaterial({
    color: 0xffffff,
    transparent: true,
    opacity: 0,
    map: null,
  });
  const plane = new Mesh(geometry, material);
  root.add(plane);

  // Load texture asynchronously (cached)
  let loadedTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTexture = tex;
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Text content
  const items =
    config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];
  for (const item of items) {
    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 96,
      color: config.intent?.visualSpec?.colors?.paper ?? '#e8ecf2',
      align: 'center',
    });
    root.add(txt);
  }

  // Entrance animation (translate up and fade in)
  const tl = gsap.timeline();
  tl.from(plane.position, {
    y: 0.4,
    duration: 0.7,
    ease: 'power3.out',
  });
  tl.to(material, {
    opacity: 1,
    duration: 0.7,
    ease: 'power3.out',
  }, 0);

  // Handlers placeholder
  root.userData.handlers = {};

  // Cleanup routine
  root.userData.cleanup = () => {
    tl.kill();
    geometry.dispose();
    material.dispose();
    if (loadedTexture) loadedTexture.dispose();
    // Dispose any child text objects
    root.traverse((child) => {
      if (child.isMesh) {
        if (child.geometry) child.geometry.dispose();
        if (child.material) child.material.dispose();
      }
    });
  };

  return root;
}
